<template>
  <div class="my-box" v-if="myInfo">
    <div class="scroll-box">
      <div class="header main-color-bg">
        <div class="leader-info">
          <div class="name" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=editNickname')"><span>{{myInfo.user.nickname}}</span><i class="icon iconfont">&#xe7a1;</i></div>
          <div style="padding: 10px 0;">团长ID：{{myInfo.leader_info.id}}
             <span class="signIn" v-if="myInfo.today_sign == 0">已签到 </span><span class="signIn" v-else-if="myInfo.today_sign == 1"  @click="clickSignIn">未签到 </span>
          </div>
        </div>
        <div class="img-box">
          <img :src="myInfo.user.avatar" alt="">
        </div>
      </div>
      <div class="content-wrapper">
        <div class="item-box">
          <div class="title">
            <span class="left">我的钱包</span>
          </div>
          <div class="list">
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=My&a=my_money')">
              <div class="num main-color-font">{{myInfo.user.now_money}}</div>
              <div>余额</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=My&a=integral')">
              <div class="num main-color-font">{{myInfo.user.score_count}}</div>
              <div>积分</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=My&a=card_list&coupon_type=system')">
              <div class="num main-color-font">{{myInfo.coupon_number}}</div>
              <div>优惠券</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=My&a=levelUpdate')">
              <div class="num main-color-font">{{myInfo.user.lname == '' ? '无' : myInfo.user.lname}}</div>
              <div>等级</div>
            </div>
          </div>
        </div>
        <div class="item-box">
          <div class="title" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=myOrder')">
            <span class="left">我的订单</span>
            <span class="right" >查看全部<i class="icon iconfont">&#xe603;</i></span>
          </div>
          <div class="list">
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=myOrder&status=0')">
              <div class="icon iconfont">&#xe60e;</div>
              <div>待付款</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=myOrder&status=1,5,7')">
              <div class="icon iconfont">&#xe6f0;</div>
              <div>未到货</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=myOrder&status=6,8')">
              <div class="icon iconfont">&#xe63e;</div>
              <div>待自提</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=myOrder&status=2,3')">
              <div class="icon iconfont">&#xe626;</div>
              <div>已自提</div>
            </div>
             <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=myOrder&status=4,9')">
              <div class="icon iconfont">&#xe70b;</div>
              <div>售后</div>
            </div>
          </div>
        </div>
        <div class="item-box" v-if="myInfo.is_self != 1">
          <div class="title"  @click="goUrl('/wap.php?g=Wap&c=Village_group&a=apply')">
            <span class="left">申请成为团长</span>
            <span class="right"><i class="icon iconfont">&#xe603;</i></span>
          </div>
        </div>
        <div class="item-box">
          <div class="" v-if="$global.config.config.open_bbs == 1" >
             <div class="title title_line" @click="goUrl('/wap.php?g=Wap&c=Gift&a=index')">
              <span class="left">积分商城</span>
              <span class="right"><i class="icon iconfont">&#xe603;</i></span>
            </div>
             <div class="title title_line" @click="goUrl('/packapp/merchant/login.html?back=index')">
              <span class="left">申请成为供应商</span>
              <span class="right" ><i class="icon iconfont">&#xe603;</i></span>
            </div>
            <div class="title title_line" @click="goUrl('/wap.php?g=Wap&c=My&a=my_spread')">
              <span class="left">我的推广</span>
              <span class="right" ><i class="icon iconfont">&#xe603;</i></span>
            </div>
          </div>
           <div class="title no-border" @click="contactService"  v-if="myInfo.open_im == 1">
            <span class="left">联系客服</span>
            <span class="right" ><i class="icon iconfont">&#xe603;</i></span>
          </div>

        </div>
        <div class="item-box" v-if="myInfo.is_self == 1">
          <div class="title">
            <span class="left">我是团长</span>
          </div>
          <div class="list">
            <div class="item" @click="scanHandle">
              <div class="icon iconfont">&#xe627;</div>
              <div>扫码核销</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=leaderOrder&leader_id=31')">
              <div class="icon iconfont">&#xe638;</div>
              <div>订单管理</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=reward')">
              <div class="icon iconfont">&#xe60f;</div>
              <div>我的佣金</div>
            </div>
            <div class="item" @click="goUrl('/wap.php?g=Wap&c=Village_group&a=statistics_list')">
              <div class="icon iconfont">&#xe61e;</div>
              <div>数据统计</div>
            </div>
          </div>
        </div>
        <div class="item-box qcode-box" v-if="myInfo.code_img">
          <div class="title">
            <span class="left main-color-font">提货时，向团长出示二维码提货</span>
          </div>
          <div class="img-box">
            <div class="qcode"><img :src="myInfo.code_img" alt=""></div>
            <div class="desc main-color-font">您也可以</div>
            <div class="btn"><button class="main-color-font main-color-border" @click="openMask">使用提货码</button></div>
          </div>
        </div>
      </div>
    </div>
    <div class="qcode-mask" v-show="showQcodeMask" @click="closeMask">
      <div class="content" @click.stop="prventClick">
        <div class="title">您的提货码</div>
        <div class="num-list">
          <div class="item" v-for="(item, index) in myInfo.code" :key="index">{{item}}</div>
        </div>
        <div class="tip">当日有效</div>
        <div class="close" @click="closeMask">×</div>
      </div>
    </div>
    <mt-actionsheet
      :actions="actions"
      v-model="showPhone">
    </mt-actionsheet>
  </div>
</template>

<script>
export default {
  name: 'My',
  data () {
    return {
      showQcodeMask: false,
      ticket: '',
      myInfo: '',
      leader_id: '',
      actions: [],
      showPhone: false
    }
  },
  created () {
    if (this.$util.checkWeixin() && this.$util.checkAndroid()) {
      this.$util.getWxconfig()
    }
  },
  activated () {
    console.log(this.$util.storage.get('ticket'))
    if (!this.$util.storage.get('ticket')) {
      this.$util.checkLogin()
    } else if (!this.myInfo) {
      this.leader_id = this.$util.storage.get('leader_id')
      this.ticket = this.$util.storage.get('ticket')
      this.getMyInfo()
    }
  },
  destroyed () {
    this.showQcodeMask = false
  },
  methods: {
    // 签到
    clickSignIn () {
      this.leader_id = this.$util.storage.get('leader_id')
      let res = this.$api.getSign({ leader_id: this.leader_id })
      if (!res) return
      this.getMyInfo()
    },
    scanHandle () {
      if (this.$util.checkWeixin()) {
        let _this = this
        this.$wx.scanQRCode({
          desc: 'scanQRCode desc',
          needResult: 1,
          scanType: ['qrCode', 'barCode'],
          success: function (res) {
            if (isNaN(res.resultStr)) {
              this.$messageBox.alert('此核销码不存在！')
            } else {
              var url = '/wap.php?g=Wap&c=Village_group&a=leaderOrder&code=' + res.resultStr
              if (_this.$util.checkWeixinApp()) {
                if (url.indexOf('http://') === -1 && url.indexOf('https://') === -1) {
                  url = 'https://' + document.domain + url
                }
                this.$wx.miniProgram.navigateTo({ url: '/pages/webview/webview?webview_url=' + encodeURIComponent(url) + '&webview_title=' + encodeURIComponent('打开新页面') })
              } else {
                location.href = url
              }
            }
          },
          error: function (res) {
            this.$toast('微信返回错误！请稍后重试！')
          },
          fail: function (res) {
            this.$toast('无法使用二维码功能！')
          }
        })
      } else {
        this.$toast('您不是微信访问，无法使用二维码功能！')
      }
    },
    // 联系客服
    contactService () {
      this.showPhone = true
    },
    selectPhone (e) {
      window.location.href = 'tel://' + e.name
    },
    openKefu () {
      location.href = process.env.VUE_APP_BASE_API + this.myInfo.kefu_url + '&ticket=' + this.ticket + '&device_id=packapp'
    },
    goUrl (url) {
      location.href = process.env.VUE_APP_BASE_API + url + '&ticket=' + this.ticket + '&device_id=packapp'
    },
    openMask () {
      this.showQcodeMask = true
    },
    closeMask () {
      this.showQcodeMask = false
    },
    prventClick () {
      return false
    },
    async getMyInfo () {
      let res = await this.$api.getMyInfo({ leader_id: this.$util.storage.get('leader_id') })
      if (!res) return
      res.code = res.code.split('')
      if (res.site_phone) {
        let arr = []
        res.site_phone = res.site_phone.split(' ')
        res.site_phone.map(item => {
          arr.push({ name: item, method: this.selectPhone })
        })
        this.actions = arr
      }
      if (res.kefu_url) {
        this.actions.push({ name: '在线客服', method: this.openKefu })
      }
      this.myInfo = res;
    }
  }
}
</script>

<style lang="stylus" scoped>
.signIn
  border 1px solid #fff
  padding  0px 10px
  border-radius 10px
  margin-left   20px
.my-box
  background #f8f8f8
  position relative
  .scroll-box
    height 100%
    overflow-y auto
    -webkit-overflow-scrolling touch
    .header
      background $color-main
      height 130px
      flexbox()
      justify-content space-between
      color #fff
      padding 30px 15px
      box-sizing border-box
      .leader-info
        .name
          font-size 16px
          margin 5px 0
          .icon
            padding-left 5px
            vertical-align middle
      .img-box
        width 45px
        height 45px
        border-radius 50%
        overflow hidden
        img
          width 100%
          height 100%
          object-fit cover
    .content-wrapper
      padding 0 15px
      margin-top -20px
      .item-box
        background #fff
        box-shadow 0 5px 10px #e5e5e5
        border-radius 6px
        padding 0 10px
        margin-bottom 20px
        color #333
        .title
          height 60px
          flexbox()
          align-items center
          justify-content space-between
          border-bottom 1PX solid #efefef
          .left
            font-size 14px
          .right
            color #999
            .icon
              font-size 12px
              padding-left 5px
          &.no-border
            border-bottom none
        .title_line
           height 40px
        .list
          flexbox()
          align-items center
          text-align center
          .item
            flex-grow 1
            padding 20px 0
            line-height 1.5
            .num
              color $color-main
              font-size 14px
            .icon
              font-size 24px
              color #999
        &.qcode-box
          text-align center
          margin-bottom 50px
          .title
            justify-content center
            color $color-main
            .left
              font-size 15px
              font-weight 500
          .img-box
            .qcode
              width 200px
              height 200px
              margin 20px auto 10px
              img
                width 100%
                height 100%
            .desc
              color $color-main
            .btn
              padding 10px 0 20px
              button
                color $color-main
                border 1PX solid $color-main
                background #fff
                padding 5px 20px
                border-radius 15px
                font-size 14px
                &:active
                  opacity 0.6
  .qcode-mask
    position absolute
    top 0
    left 0
    bottom 0
    right 0
    background rgba(0, 0, 0, .65)
    flexbox()
    align-items center
    .content
      margin 0 25px
      width 100%
      border-radius 6px
      background #fff
      text-align center
      position relative
      .title
        font-size 16px
        padding 20px 0
      .num-list
        padding 20px 0
        flexbox()
        justify-content center
        .item
          font-size 24px
          font-weight 500
          padding 14px 8px
          border-radius 4px
          box-shadow 0 2px 5px #e5e5e5
          border 1PX solid #efefef
          margin-right 5px
          &:last-child
            margin-right 0
      .tip
        padding 20px 0
        color #999
      .close
        position absolute
        right 0
        top 0
        padding 10px
        color #bbb
        font-size 24px
</style>
